Lemma lapi_1RB1LA_1LA1RC_0LA0RD_0LB1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
