    rewrite (srun_sound tm false true chz_1RB1LA_1LA1RC_0LA0RD_0LB1RC Z0_1RB1LA_1LA1RC_0LA0RD_0LB1RC Z1_1RB1LA_1LA1RC_0LA0RD_0LB1RC 0 4
