(** ** The lap *)

Lemma lap_1RB1LA_1LA1RC_0LA0RD_0LB1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_1LA1RC_0LA0RD_0LB1RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_1LA1RC_0LA0RD_0LB1RC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_1LA1RC_0LA0RD_0LB1RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 2)).
Proof.
  exists 14.
  assert (H : match csteps tm 14 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 14 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_1LA1RC_0LA0RD_0LB1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_1LA1RC_0LA0RD_0LB1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_1LA1RC_0LA0RD_0LB1RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_1LA1RC_0LA0RD_0LB1RC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LA_1LA1RC_0LA0RD_0LB1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LA_1LA1RC_0LA0RD_0LB1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LA_1LA1RC_0LA0RD_0LB1RC t p (pow2 j)).
  - exists (4 * j + 7), (cden [] [] j BB1_1RB1LA_1LA1RC_0LA0RD_0LB1RC). split;
      [| exact (gbo_1RB1LA_1LA1RC_0LA0RD_0LB1RC j)].
    rewrite (gso_1RB1LA_1LA1RC_0LA0RD_0LB1RC p j E).
    exact (srun_sound tm true true chb_1RB1LA_1LA1RC_0LA0RD_0LB1RC B0_1RB1LA_1LA1RC_0LA0RD_0LB1RC BB1_1RB1LA_1LA1RC_0LA0RD_0LB1RC 4 7
             run_boot_1RB1LA_1LA1RC_0LA0RD_0LB1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LA_1LA1RC_0LA0RD_0LB1RC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LA_1LA1RC_0LA0RD_0LB1RC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_1LA1RC_0LA0RD_0LB1RC : forall t, ~ In t pins_1RB1LA_1LA1RC_0LA0RD_0LB1RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
