    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LA_1LA1RC_0LA0RD_0LB1RC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LA_1LA1RC_0LA0RD_0LB1RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
