  - apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_1LA1RC_0LA0RD_1LB1RC p (xO (xI (pow2 j')))).
    + exists (4 * j' + 21), (cden [] [] j' BB1_1RB1LA_1LA1RC_0LA0RD_1LB1RC).
      split; [lia|]. split; [| exact (gbo_1RB1LA_1LA1RC_0LA0RD_1LB1RC j')].
      rewrite (gso_1RB1LA_1LA1RC_0LA0RD_1LB1RC p j' E).
      exact (srun_sound tm true true chb_1RB1LA_1LA1RC_0LA0RD_1LB1RC B0_1RB1LA_1LA1RC_0LA0RD_1LB1RC BB1_1RB1LA_1LA1RC_0LA0RD_1LB1RC 4 21
               run_boot_1RB1LA_1LA1RC_0LA0RD_1LB1RC [] [] j' ltac:(reflexivity) ltac:(reflexivity)).
    + exists (4 * j' + 12), (cden [] [] j' B1_1RB1LA_1LA1RC_0LA0RD_1LB1RC).
      split; [| exact (geo_1RB1LA_1LA1RC_0LA0RD_1LB1RC p j' E)].
      rewrite (gxi_1RB1LA_1LA1RC_0LA0RD_1LB1RC j').
      exact (srun_sound tm true true che_1RB1LA_1LA1RC_0LA0RD_1LB1RC BE0_1RB1LA_1LA1RC_0LA0RD_1LB1RC B1_1RB1LA_1LA1RC_0LA0RD_1LB1RC 4 12
               run_exit_1RB1LA_1LA1RC_0LA0RD_1LB1RC [] [] j' ltac:(reflexivity) ltac:(reflexivity)).
Qed.

