    step counts AND exact configurations -- for 192 interior anchors (interior); 6 overflow phases, j = 2..7 (246 inner laps) (nested overflow).
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter Alph_10_11_11 LapCertGlue LapCertGlueLift IXPGadgets NestedLap NestedLapLift ILCounter.
Import TNF_QH.
Import LapDecider.
Import BBBT4_Statement.
Import WrapTr.
Import AnchorVisitsTr.
Import LapGlueTr.
Import ListNotations.

Definition mk_1RB1LA_1LA1RC_0LC0RD_0LB1RC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1LA_1LA1RC_0LC0RD_0LB1RC.

(** 1RB1LA_1LA1RC_0LC0RD_0LB1RC *)
Definition tm_1RB1LA_1LA1RC_0LC0RD_0LB1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S0 DL StC | StC, S1 => mk S0 DR StD
  | StD, S0 => mk S0 DL StB | StD, S1 => mk S1 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LA_1LA1RC_0LC0RD_0LB1RC : list Instr := [].
Definition tmw_1RB1LA_1LA1RC_0LC0RD_0LB1RC : TM := tm_wrap_trs tm_1RB1LA_1LA1RC_0LC0RD_0LB1RC pins_1RB1LA_1LA1RC_0LC0RD_0LB1RC.
Local Notation tm := tmw_1RB1LA_1LA1RC_0LC0RD_0LB1RC.

Definition Cc_1RB1LA_1LA1RC_0LC0RD_0LB1RC (p : positive) : cconf := (StC, (Ap_Alph_10_11_11 p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1LA_1LA1RC_0LC0RD_0LB1RC.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1LA_1LA1RC_0LC0RD_0LB1RC : sconf := mkC StC (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB1LA_1LA1RC_0LC0RD_0LB1RC : sconf := mkC StC (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_1RB1LA_1LA1RC_0LC0RD_0LB1RC : list lstep := [SWin 6].

Lemma run_z_1RB1LA_1LA1RC_0LC0RD_0LB1RC : srun tm false true chz_1RB1LA_1LA1RC_0LC0RD_0LB1RC Z0_1RB1LA_1LA1RC_0LC0RD_0LB1RC = Some (Z1_1RB1LA_1LA1RC_0LC0RD_0LB1RC, 0, 6).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_1RB1LA_1LA1RC_0LC0RD_0LB1RC : sconf := mkC StC (mkS [S1;S1] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition P1_1RB1LA_1LA1RC_0LC0RD_0LB1RC : sconf := mkC StC (mkS [S1;S0] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chp_1RB1LA_1LA1RC_0LC0RD_0LB1RC : list lstep := [SWin 4; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_p_1RB1LA_1LA1RC_0LC0RD_0LB1RC : srun tm false true chp_1RB1LA_1LA1RC_0LC0RD_0LB1RC P0_1RB1LA_1LA1RC_0LC0RD_0LB1RC = Some (P1_1RB1LA_1LA1RC_0LC0RD_0LB1RC, 4, 10).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1LA_1LA1RC_0LC0RD_0LB1RC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1LA_1LA1RC_0LC0RD_0LB1RC : sconf := mkC StC (mkS [] [S1;S0] 1 1 [S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StB *)
Definition Cin_1RB1LA_1LA1RC_0LC0RD_0LB1RC (v : positive) : cconf := (StB, (Ip v ++ [S1], S0, [])).
Local Notation Cin := Cin_1RB1LA_1LA1RC_0LC0RD_0LB1RC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1LA_1LA1RC_0LC0RD_0LB1RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1LA_1LA1RC_0LC0RD_0LB1RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chn_1RB1LA_1LA1RC_0LC0RD_0LB1RC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SRotR 1; SWin 1; SCycR 2; SWinR 2].

Lemma run_inner_1RB1LA_1LA1RC_0LC0RD_0LB1RC : srun tm false true chn_1RB1LA_1LA1RC_0LC0RD_0LB1RC AI0_1RB1LA_1LA1RC_0LC0RD_0LB1RC = Some (AI1_1RB1LA_1LA1RC_0LC0RD_0LB1RC, 4, 6).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LA_1LA1RC_0LC0RD_0LB1RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chb_1RB1LA_1LA1RC_0LC0RD_0LB1RC : list lstep := [SRotL 1; SWin 3; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SRotR 1; SWin 1; SCycR 2; SWin 2].

Lemma run_boot_1RB1LA_1LA1RC_0LC0RD_0LB1RC : srun tm true true chb_1RB1LA_1LA1RC_0LC0RD_0LB1RC B0_1RB1LA_1LA1RC_0LC0RD_0LB1RC = Some (BB1_1RB1LA_1LA1RC_0LC0RD_0LB1RC, 4, 9).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LA_1LA1RC_0LC0RD_0LB1RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1LA_1LA1RC_0LC0RD_0LB1RC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 1; SWinR 1; SFoldL 1].

Lemma run_exit_1RB1LA_1LA1RC_0LC0RD_0LB1RC : srun tm true true che_1RB1LA_1LA1RC_0LC0RD_0LB1RC BE0_1RB1LA_1LA1RC_0LC0RD_0LB1RC = Some (B1_1RB1LA_1LA1RC_0LC0RD_0LB1RC, 4, 7).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_1RB1LA_1LA1RC_0LC0RD_0LB1RC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_1RB1LA_1LA1RC_0LC0RD_0LB1RC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1LA_1LA1RC_0LC0RD_0LB1RC, cden, Z0_1RB1LA_1LA1RC_0LC0RD_0LB1RC, Z1_1RB1LA_1LA1RC_0LC0RD_0LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P0_1RB1LA_1LA1RC_0LC0RD_0LB1RC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P1_1RB1LA_1LA1RC_0LC0RD_0LB1RC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1LA_1LA1RC_0LC0RD_0LB1RC, cden, P0_1RB1LA_1LA1RC_0LC0RD_0LB1RC, P1_1RB1LA_1LA1RC_0LC0RD_0LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1LA_1LA1RC_0LC0RD_0LB1RC p q0 E) as (HA & HB).
    exists (0 * 0 + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1LA_1LA1RC_0LC0RD_0LB1RC Z0_1RB1LA_1LA1RC_0LC0RD_0LB1RC Z1_1RB1LA_1LA1RC_0LC0RD_0LB1RC 0 6
               run_z_1RB1LA_1LA1RC_0LC0RD_0LB1RC (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1LA_1LA1RC_0LC0RD_0LB1RC p j' q0 E) as (HA & HB).
    exists (4 * j' + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LA_1LA1RC_0LC0RD_0LB1RC P0_1RB1LA_1LA1RC_0LC0RD_0LB1RC P1_1RB1LA_1LA1RC_0LC0RD_0LB1RC 4 10
               run_p_1RB1LA_1LA1RC_0LC0RD_0LB1RC (Ap_Alph_10_11_11 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_1LA1RC_0LC0RD_0LB1RC.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_1RB1LA_1LA1RC_0LC0RD_0LB1RC, cden, B0_1RB1LA_1LA1RC_0LC0RD_0LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_1LA1RC_0LC0RD_0LB1RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_1LA1RC_0LC0RD_0LB1RC
             = (StC, (rep [S1;S0] (S j) ++ [S1;S1], S0, []))).
  { unfold cden, B1_1RB1LA_1LA1RC_0LC0RD_0LB1RC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LA_1LA1RC_0LC0RD_0LB1RC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LA_1LA1RC_0LC0RD_0LB1RC. reflexivity.
Qed.

Lemma gsn_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_1RB1LA_1LA1RC_0LC0RD_0LB1RC.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_1RB1LA_1LA1RC_0LC0RD_0LB1RC, cden, AI0_1RB1LA_1LA1RC_0LC0RD_0LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB1LA_1LA1RC_0LC0RD_0LB1RC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_1RB1LA_1LA1RC_0LC0RD_0LB1RC, cden, AI1_1RB1LA_1LA1RC_0LC0RD_0LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 6), (cden (Ip q0 ++ [S1]) [] i AI1_1RB1LA_1LA1RC_0LC0RD_0LB1RC).
  split; [lia|]. split; [| exact (gen_1RB1LA_1LA1RC_0LC0RD_0LB1RC v i q0 E)].
  rewrite (gsn_1RB1LA_1LA1RC_0LC0RD_0LB1RC v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_1LA1RC_0LC0RD_0LB1RC AI0_1RB1LA_1LA1RC_0LC0RD_0LB1RC AI1_1RB1LA_1LA1RC_0LC0RD_0LB1RC 4 6
           run_inner_1RB1LA_1LA1RC_0LC0RD_0LB1RC (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall j, lift (cden [] [] j BB1_1RB1LA_1LA1RC_0LC0RD_0LB1RC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_1LA1RC_0LC0RD_0LB1RC = (StB, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB1LA_1LA1RC_0LC0RD_0LB1RC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1LA_1LA1RC_0LC0RD_0LB1RC. rewrite epow2_1RB1LA_1LA1RC_0LC0RD_0LB1RC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LA_1LA1RC_0LC0RD_0LB1RC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LA_1LA1RC_0LC0RD_0LB1RC.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LA_1LA1RC_0LC0RD_0LB1RC, cden, BE0_1RB1LA_1LA1RC_0LC0RD_0LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1LA_1LA1RC_0LC0RD_0LB1RC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_1LA1RC_0LC0RD_0LB1RC p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_1RB1LA_1LA1RC_0LC0RD_0LB1RC).
    split; [lia|]. split; [| exact (gbo_1RB1LA_1LA1RC_0LC0RD_0LB1RC j)].
    rewrite (gso_1RB1LA_1LA1RC_0LC0RD_0LB1RC p j E).
    exact (srun_sound tm true true chb_1RB1LA_1LA1RC_0LC0RD_0LB1RC B0_1RB1LA_1LA1RC_0LC0RD_0LB1RC BB1_1RB1LA_1LA1RC_0LC0RD_0LB1RC 4 9
             run_boot_1RB1LA_1LA1RC_0LC0RD_0LB1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 7), (cden [] [] j B1_1RB1LA_1LA1RC_0LC0RD_0LB1RC).
    split; [| exact (geo_1RB1LA_1LA1RC_0LC0RD_0LB1RC p j E)].
    rewrite (gxi_1RB1LA_1LA1RC_0LC0RD_0LB1RC j).
    exact (srun_sound tm true true che_1RB1LA_1LA1RC_0LC0RD_0LB1RC BE0_1RB1LA_1LA1RC_0LC0RD_0LB1RC B1_1RB1LA_1LA1RC_0LC0RD_0LB1RC 4 7
             run_exit_1RB1LA_1LA1RC_0LC0RD_0LB1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LA_1LA1RC_0LC0RD_0LB1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_1LA1RC_0LC0RD_0LB1RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_1LA1RC_0LC0RD_0LB1RC p j' E).
Qed.

(** ** Bootstrap *)

