  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1LA1RC_0LD0RB____1LA B0_1RB1LA_1LA1RC_0LD0RB____1LA B1_1RB1LA_1LA1RC_0LD0RB____1LA 4 13 p j' [] []).
    + exact run_ovf_1RB1LA_1LA1RC_0LD0RB____1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_1LA1RC_0LD0RB____1LA p j' E).
    + exact (geo_1RB1LA_1LA1RC_0LD0RB____1LA p j' E).
    + lia.
