      exact (srun_sound tm true true chb_1RB1LA_1LA1RC_0RD0RB_0LD0LA B0_1RB1LA_1LA1RC_0RD0RB_0LD0LA BB1_1RB1LA_1LA1RC_0RD0RB_0LD0LA 4 11
               run_boot_1RB1LA_1LA1RC_0RD0RB_0LD0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LA_1LA1RC_0RD0RB_0LD0LA p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (4 * j + 12), (cden [] [] j BM1_1RB1LA_1LA1RC_0RD0RB_0LD0LA).
