      rewrite (gxi_1RB1LA_1LA1RC_0RD0RB_0LD0LA j).
      exact (srun_sound tm true true chm_1RB1LA_1LA1RC_0RD0RB_0LD0LA BM0_1RB1LA_1LA1RC_0RD0RB_0LD0LA BM1_1RB1LA_1LA1RC_0RD0RB_0LD0LA 4 12
               run_shift_1RB1LA_1LA1RC_0RD0RB_0LD0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (4 * j + 21), (cden [] [] j B1_1RB1LA_1LA1RC_0RD0RB_0LD0LA).
    split; [| exact (geo_1RB1LA_1LA1RC_0RD0RB_0LD0LA p j E)].
    rewrite (gxi2_1RB1LA_1LA1RC_0RD0RB_0LD0LA j).
