Lemma gsi_1RB1LA_1LA1RC_1LD0RD_0LB1RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB1LA_1LA1RC_1LD0RD_0LB1RC.
