(** ** The lap *)

Lemma lap_1RB1LA_1LA1RC_1LD0RD_0LB1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
