    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1LA1RC_1LD0RD_0LB1RC B0_1RB1LA_1LA1RC_1LD0RD_0LB1RC B1_1RB1LA_1LA1RC_1LD0RD_0LB1RC 4 11 p j' [] []).
    + exact run_ovf_1RB1LA_1LA1RC_1LD0RD_0LB1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_1LA1RC_1LD0RD_0LB1RC p j' E).
    + exact (geo_1RB1LA_1LA1RC_1LD0RD_0LB1RC p j' E).
    + lia.
Qed.

