    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LA_1LB1RC_0LA0RD_1LB1RC P0_1RB1LA_1LB1RC_0LA0RD_1LB1RC P1_1RB1LA_1LB1RC_0LA0RD_1LB1RC 4 8
