  - destruct (lapi_1RB1LA_1LC0RB_0LC0RD_0LA1RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1LC0RB_0LC0RD_0LA1RD B0_1RB1LA_1LC0RB_0LC0RD_0LA1RD B1_1RB1LA_1LC0RB_0LC0RD_0LA1RD 4 16 p j' [] []).
    + exact run_ovf_1RB1LA_1LC0RB_0LC0RD_0LA1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_1LC0RB_0LC0RD_0LA1RD p j' E).
    + exact (geo_1RB1LA_1LC0RB_0LC0RD_0LA1RD p j' E).
    + lia.
Qed.

