(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LA_1LC0RB_1LD0RA_0LC1RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB1LA_1LC0RB_1LD0RA_0LC1RA.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_1RB1LA_1LC0RB_1LD0RA_0LC1RA, cden, A0_1RB1LA_1LC0RB_1LD0RA_0LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0;S1;S0] where the anchor has [S0;S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1LA_1LC0RB_1LD0RA_0LC1RA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB1LA_1LC0RB_1LD0RA_0LC1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_1RB1LA_1LC0RB_1LD0RA_0LC1RA, cden, A1_1RB1LA_1LC0RB_1LD0RA_0LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
