Lemma gsi_1RB1LA_1LC0RB_1LD1LA_0LC0RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB1LA_1LC0RB_1LD1LA_0LC0RA.
