  - destruct (lapi_1RB1LA_1LC0RB_1LD1LA_0LC0RA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1LC0RB_1LD1LA_0LC0RA B0_1RB1LA_1LC0RB_1LD1LA_0LC0RA B1_1RB1LA_1LC0RB_1LD1LA_0LC0RA 4 7 p j' [] []).
    + exact run_ovf_1RB1LA_1LC0RB_1LD1LA_0LC0RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_1LC0RB_1LD1LA_0LC0RA p j' E).
    + exact (geo_1RB1LA_1LC0RB_1LD1LA_0LC0RA p j' E).
    + lia.
