(** ** The lap *)

Lemma lap_1RB1LA_1LC0RB_1LD1RB_0LC1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
