  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_1LC0RB_1LD1RB_0LC1RA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1LC0RB_1LD1RB_0LC1RA B0_1RB1LA_1LC0RB_1LD1RB_0LC1RA B1_1RB1LA_1LC0RB_1LD1RB_0LC1RA 4 23 p j' [] []).
    + exact run_ovf_1RB1LA_1LC0RB_1LD1RB_0LC1RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_1LC0RB_1LD1RB_0LC1RA p j' E).
    + exact (geo_1RB1LA_1LC0RB_1LD1RB_0LC1RA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_1LC0RB_1LD1RB_0LC1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 23.
  assert (H : match csteps tm 23 c0 with
