Definition chn_1RB1LA_1LC0RB_1LD1RC_0LC0RA : list lstep := [SWin 6; SCycL 2 0; SWin 4; SCycR 2].

Lemma run_inner_1RB1LA_1LC0RB_1LD1RC_0LC0RA : srun tm false true chn_1RB1LA_1LC0RB_1LD1RC_0LC0RA AI0_1RB1LA_1LC0RB_1LD1RC_0LC0RA = Some (AI1_1RB1LA_1LC0RB_1LD1RC_0LC0RA, 4, 10).
