Lemma lapin_1RB1LA_1LC0RB_1LD1RC_0LC0RA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 10), (cden (Ip q0 ++ [S1]) [] i AI1_1RB1LA_1LC0RB_1LD1RC_0LC0RA).
  split; [lia|]. split; [| exact (gen_1RB1LA_1LC0RB_1LD1RC_0LC0RA v i q0 E)].
  rewrite (gsn_1RB1LA_1LC0RB_1LD1RC_0LC0RA v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_1LC0RB_1LD1RC_0LC0RA AI0_1RB1LA_1LC0RB_1LD1RC_0LC0RA AI1_1RB1LA_1LC0RB_1LD1RC_0LC0RA 4 10
           run_inner_1RB1LA_1LC0RB_1LD1RC_0LC0RA (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
