(** ** The lap *)

Lemma lap_1RB1LA_1LC0RD_1LB0RA_0RB0LB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_1LC0RD_1LB0RA_0RB0LB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1LC0RD_1LB0RA_0RB0LB B0_1RB1LA_1LC0RD_1LB0RA_0RB0LB B1_1RB1LA_1LC0RD_1LB0RA_0RB0LB 4 8 p j' [] []).
    + exact run_ovf_1RB1LA_1LC0RD_1LB0RA_0RB0LB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_1LC0RD_1LB0RA_0RB0LB p j' E).
    + exact (geo_1RB1LA_1LC0RD_1LB0RA_0RB0LB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_1LC0RD_1LB0RA_0RB0LB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 4.
  assert (H : match csteps tm 4 c0 with
