  intros p j q0 E. exists (6 * j + 4). split; [lia|].
  rewrite (gsi_1RB1LA_1LC1RC_0RA0LD_0RB1LD p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1LA_1LC1RC_0RA0LD_0RB1LD A0_1RB1LA_1LC1RC_0RA0LD_0RB1LD A1_1RB1LA_1LC1RC_0RA0LD_0RB1LD 6 4
             run_int_1RB1LA_1LC1RC_0RA0LD_0RB1LD (Jp q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1LA_1LC1RC_0RA0LD_0RB1LD p j q0 E).
