Lemma geo_1RB1LA_1LC1RC_1RD0RB_0LD0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_1LC1RC_1RD0RB_0LD0LA) = lift (Cc (Pos.succ p)).
