  unfold Cin_1RB1LA_1LC1RC_1RD0RB_0LD0LA, cden, BE0_1RB1LA_1LC1RC_1RD0RB_0LD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
