    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_1LC1RD_0RB0RB_0LA1RC (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_1LC1RD_0RB0RB_0LA1RC [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SWinL 6; SCycR 3; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
